const {test}=require('node:test');const assert=require('node:assert/strict');
const {createRegistry}=require('../app-actions.js');
const target={sessionId:'session-1234567890',documentId:'document-1234567890',slug:'/playground',search:'',buildId:'build-1',enabled:true};
function fixture(){let revision=1,value=0;const registry=createRegistry({identity:()=>target});registry.register('board',{revision:()=>revision,read:()=>({value}),actions:{add:{schema:{type:'object',properties:{amount:{type:'integer',minimum:1,maximum:5}},required:['amount']},run:async({amount})=>{value+=amount;revision++;return {value};}}}});return registry;}
const command=(extra={})=>({id:'command-1234567890',target:{...target},action:'board.add',arguments:{amount:2},expectedRevision:1,expiresAt:Date.now()+30000,...extra});
test('typed discovery, completion state and idempotent retry',async()=>{const r=fixture(),c=command();assert.equal(r.describe().providers[0].actions[0].name,'board.add');const a=await r.execute(c);assert.equal(a.status,'succeeded');assert.equal(a.afterRevision,2);assert.equal(a.state.value,2);assert.deepEqual(await r.execute(c),a);await assert.rejects(r.execute({...c,arguments:{amount:3}}),/reused/);});
test('wrong target, revision, expiry and invalid arguments cannot mutate',async()=>{for(const patch of [{target:{...target,documentId:'previous-page-load'}},{target:{...target,slug:'/wrong'}},{target:{...target,buildId:'wrong'}},{expectedRevision:0},{expiresAt:1},{arguments:{amount:6}},{arguments:{amount:2,extra:true}},{action:'board.delete'}]){const r=fixture();await assert.rejects(r.execute(command(patch)));assert.equal(r.describe().providers[0].revision,1);}});
test('paused targets and concurrent actions rejected; errors are failed receipts',async()=>{const r=fixture();target.enabled=false;await assert.rejects(r.execute(command()),/unavailable/);target.enabled=true;const first=r.execute(command());await assert.rejects(r.execute(command({id:'command-1234567891'})),/running/);await first;const bad=createRegistry({identity:()=>target});bad.register('board',{revision:()=>1,read:()=>({}),actions:{add:{schema:{type:'object',properties:{}},run:()=>{throw Error('render failed');}}}});assert.equal((await bad.execute(command({arguments:{}}))).status,'failed');});
